public int maximumToys(int[] prices, int k) {
    int n = prices.length;
    int best = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        long total = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) {
                total += prices[i];
                count++;
            }
        }
        if (total <= k) {
            best = Math.max(best, count);
        }
    }
    return best;
}

