def maximum_toys(prices: list[int], k: int) -> int:
    n = len(prices)
    best = 0
    for mask in range(1 << n):
        total = 0
        count = 0
        for i in range(n):
            if mask & (1 << i):
                total += prices[i]
                count += 1
        if total <= k:
            best = max(best, count)
    return best

